<?php

declare(strict_types=1);

namespace Identity\UI\Controller\Account;

use Shared\Application\Crypto\TokenGenerator;

/**
 * Plain backup codes are generated by the UI (like ids) and passed to the command, which stores their hashes only.
 * They exist nowhere else than in the response of the POST.
 */
final class BackupCodes
{
    public const int COUNT = 10;

    /**
     * @return list<string>
     */
    public static function generate(TokenGenerator $tokens): array
    {
        return array_map($tokens->backupCode(...), range(1, self::COUNT));
    }
}
